const body = $('Normalize Multipart Body').first().json.body;
const documents = body.documents || [];

const parts = [];

let hasPdf = false;
for (const doc of documents) {
  if (doc.type === 'inline') {
    if (doc.mime_type === 'application/pdf' || (doc.name && doc.name.toLowerCase().endsWith('.pdf'))) hasPdf = true;
    parts.push({ inline_data: { mime_type: doc.mime_type, data: doc.base64 } });
  } else if (doc.type === 'text') {
    parts.push({ text: `[Content from ${doc.name}]:\n${doc.content}` });
  }
}

const handwrittenPrompt = `You are a professional transcription assistant. You have been given ${documents.length} document(s) containing handwritten notes, essays, or mind maps.

Your task:
1. CAREFULLY read the handwriting in each document, in the exact order they were provided.
2. UNDERSTAND the logical flow and context across all pages — they form a single continuous document.
3. TRANSCRIBE the handwriting into clean, well-structured digital text.
4. PRESERVE the author's original intent, ideas, paragraph structure, and any headings or bullet points.
5. If the handwriting contains a mind map, convert it into a logical outline or structured text.
6. Separate content from different pages with a blank line, but maintain narrative continuity.
7. Fix obvious spelling errors in the handwriting, but do NOT add, remove, or rephrase the author's ideas.
8. DO identify if the author had struck through lines or massive crossing out — this means the user has removed that content and does not want it transcribed.
9. Do NOT add any commentary, preamble, or summary — output ONLY the transcribed text.

Begin transcription now:`;

const documentPrompt = `You are a study-notes extraction assistant. The student has uploaded ${documents.length} page(s) from their study material for personal academic use.

Your task:
1. READ each page carefully in order.
2. EXTRACT the key content: headings, definitions, concepts, lists, tables, case studies, and discussion questions.
3. RESTRUCTURE the content into clean, well-organised study notes using your own wording.
4. USE clear headings (# / ## / ###) and bullet points for structure.
5. PRESERVE all factual information, names, dates, legal references, and technical terms exactly.
6. For tables, reproduce them in markdown table format.
7. For case studies or scenarios, summarise the scenario and list the discussion questions.
8. Do NOT copy sentences verbatim — paraphrase into clear study-note form while keeping all meaning.
9. Do NOT add commentary or analysis — output ONLY the restructured study notes.

Begin extraction now:`;

parts.push({ text: hasPdf ? documentPrompt : handwrittenPrompt });

const geminiPayload = {
  contents: [{ parts }],
  generationConfig: {
    temperature: 0.2,
    topP: 0.8,
    topK: 40,
    maxOutputTokens: 8192
  },
  safetySettings: [
    { category: 'HARM_CATEGORY_HARASSMENT', threshold: 'BLOCK_NONE' },
    { category: 'HARM_CATEGORY_HATE_SPEECH', threshold: 'BLOCK_NONE' },
    { category: 'HARM_CATEGORY_SEXUALLY_EXPLICIT', threshold: 'BLOCK_NONE' },
    { category: 'HARM_CATEGORY_DANGEROUS_CONTENT', threshold: 'BLOCK_NONE' }
  ]
};

return { json: { geminiPayload } };

const response = $input.first().json;
let text = '';

try {
  const candidates = (response.body && response.body.candidates) || response.candidates || [];
  if (candidates.length > 0) {
    const candidate = candidates[0];
    const reason = candidate.finishReason || '';
    if (reason === 'RECITATION') return { json: { text: '[Transcription blocked] The AI detected this may be published/copyrighted content and cannot reproduce it. Try uploading handwritten notes instead.' } };
    if (reason === 'SAFETY') return { json: { text: '[Blocked] The AI safety filters prevented processing this content.' } };
    if (candidate.content && candidate.content.parts) {
      text = candidate.content.parts.filter(p => p.text).map(p => p.text).join('\n');
    }
  }
  if (!text) throw new Error('No text extracted from Gemini response');
} catch (err) {
  throw new Error(`Gemini extraction failed: ${err.message}. Raw keys: ${JSON.stringify(Object.keys(response))}`);
}

return { json: { text: text.trim() } };

