    const cached =
      (sessionHit && sessionHit.expiresAt > now) ? sessionHit :
      (persistentHit && persistentHit.expiresAt > now) ? persistentHit :
      null;

    if (cached) {
      geminiFileParts.push({ text: `Attached PDF: ${doc.name}${doc.pageCount ? ` (${doc.pageCount} pages)` : ''}` });
      geminiFileParts.push({ file_data: { mime_type: cached.mimeType, file_uri: cached.uri } });
