      // persistent-registry round trip too.
      if (hash && !sessionRegistry[hash]) sessionRegistry[hash] = cached;
      continue;
    }

    let buffer = null;
    if (doc.fieldName) {
      try {
        buffer = await this.helpers.getBinaryDataBuffer(0, doc.fieldName);
      } catch (e) {
        buffer = null;
      }
    } else if (doc.driveFileId && doc.driveAccessToken) {
