      continue;
    }

    if (buffer.length > 50 * 1024 * 1024) {
      throw new Error(`FILE_TOO_LARGE: "${doc.name}" is ${(buffer.length / 1024 / 1024).toFixed(1)}MB, over Gemini's 50MB PDF limit`);
    }

