    if (!uploadUrl) throw new Error(`GEMINI_FILE_UPLOAD: no upload URL returned for "${doc.name}"`);

    // 2) Upload the bytes and finalize
    const uploadRes = await this.helpers.httpRequest({
      method: 'POST',
      url: uploadUrl,
      headers: {
        'Content-Length': String(buffer.length),
        'X-Goog-Upload-Offset': '0',
        'X-Goog-Upload-Command': 'upload, finalize',
      },
      body: buffer,
      json: true,
    });

    const uploaded = uploadRes.file || uploadRes;
    if (!uploaded || !uploaded.uri) throw new Error(`GEMINI_FILE_UPLOAD: no file URI returned for "${doc.name}"`);

    // 3) Poll until ACTIVE — require it explicitly rather than assuming a
    // fixed iteration count is enough (a 200+ page PDF can take a while).
    // PROCESSING keeps polling until the deadline; FAILED or any other
    // unexpected state fails fast instead of silently using a half-ready file.
    let state = uploaded.state;
    let fileName = uploaded.name;
    let uri = uploaded.uri;
    let mimeType = uploaded.mimeType || 'application/pdf';
    const pollDeadline = Date.now() + 60000; // 60s wall-clock, not a fixed try count
    while (state !== 'ACTIVE') {
      if (state === 'FAILED') throw new Error(`GEMINI_FILE_PROCESSING_FAILED: Gemini failed to process "${doc.name}"`);
      if (state !== 'PROCESSING') throw new Error(`GEMINI_FILE_PROCESSING_FAILED: unexpected state "${state}" for "${doc.name}"`);
      if (Date.now() > pollDeadline) throw new Error(`GEMINI_FILE_PROCESSING_TIMEOUT: "${doc.name}" did not become ACTIVE within 60s`);
      await new Promise(r => setTimeout(r, 1000));
      const check = await this.helpers.httpRequest({
        method: 'GET',
        url: `https://generativelanguage.googleapis.com/v1beta/${fileName}`,
        headers: { [geminiCred.name]: geminiCred.value },
        json: true,
      });
      state = check.state;
      uri = check.uri || uri;
      mimeType = check.mimeType || mimeType;
    }

    if (hash) {
      const record = { uri, mimeType, expiresAt: now + GEMINI_FILE_TTL_MS };
      sessionRegistry[hash] = record;
      newPersistentEntries[hash] = record;
    }
    geminiFileParts.push({ text: `Attached PDF: ${doc.name}${doc.pageCount ? ` (${doc.pageCount} pages)` : ''}` });
    geminiFileParts.push({ file_data: { mime_type: mimeType, file_uri: uri } });
  }
}

return [{
  json: {
    ...parsed,
    geminiFileParts,
    reuploadScannedPdfs,
    updatedGeminiFiles: sessionRegistry,
    newPersistentEntries,
  }
}];

