const hashes = Object.keys(entries);

if (hashes.length > 0) {
  const cred = await this.getCredentials('httpHeaderAuth'); // credential: "Upstash Redis REST"
  const UPSTASH_URL = 'https://sweeping-jennet-172408.upstash.io';

  for (const hash of hashes) {
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: UPSTASH_URL,
        headers: { [cred.name]: cred.value },
        body: ['SET', `gemini-file:${hash}`, JSON.stringify(entries[hash]), 'EX', '169200'],
        json: true,
      });
    } catch (e) {
      // Best-effort — a later request just re-uploads if this didn't persist.
    }
  }
}

return [$input.first()];

const body = $('Normalize Multipart Body').first().json.body || {};
const scannedPdfDocs = body.scannedPdfDocs || [];
const persistentGeminiFiles = {};

if (scannedPdfDocs.length > 0) {
  const cred = await this.getCredentials('httpHeaderAuth'); // credential: "Upstash Redis REST"
  const UPSTASH_URL = 'https://sweeping-jennet-172408.upstash.io';

  for (const doc of scannedPdfDocs) {
    if (!doc.contentHash) continue;
    try {
      const res = await this.helpers.httpRequest({
        method: 'POST',
        url: UPSTASH_URL,
        headers: { [cred.name]: cred.value },
        body: ['GET', `gemini-file:${doc.contentHash}`],
        json: true,
      });
      if (res && res.result) {
        persistentGeminiFiles[doc.contentHash] = JSON.parse(res.result);
      }
    } catch (e) {
      // Persistent lookup is an optimization, not a requirement — session
      // cache or a fresh upload still works if Redis is unavailable.
    }
  }
}

return [{ json: { persistentGeminiFiles } }];

